// Array — tamaño fijo de 3
string[] armasFijas = new string[3];
armasFijas[0] = "Espada";
armasFijas[1] = "Escudo";
armasFijas[2] = "Arco";
// armasFijas[3] = "Hacha"; // IndexOutOfRangeException!

// List<T> — tamaño dinámico
List<string> inventario = new List<string>();
inventario.Add("Espada");      // Count: 1
inventario.Add("Escudo");     // Count: 2
inventario.Add("Arco");       // Count: 3
inventario.Add("Hacha");      // Count: 4 — ¡crece!
inventario.Remove("Arco");    // Count: 3 — ¡se reduce!

// Diferencia clave de propiedades
int tamArr = armasFijas.Length;    // Array usa Length
int tamList = inventario.Count;    // List<T> usa Count

